\draw[black,thick] (3,1)--(4,1);
\draw[black,dashed] (0,1)--(3,1)--(3,0);
\path (-3,0) node[below] {$-3$} (3,0) node[below] {$3$} (0,0.5) node[left] {$\frac12$} (0,1) node[left] {$1$};
